// === Tab: mySketch ===
var beziers = [];
var NUM_BEZ = 3; // Puedes ajustar este número para más o menos curvas

function setup() {
  createCanvas(windowWidth, windowHeight);
	frameRate(30);
  colorMode(HSB);
  background("rgb(0,0,12)");
  noFill();

  // Generar curvas con puntos de control y velocidades aleatorias
	beziers = [];
  for (let i = 0; i < NUM_BEZ; i++) {
    const bez = {
      p1: { x: 0, y: random(0, 0.3) * height },
      p2: { x: random(0.25, 0.6) * width, y: random(height) },
      p3: { x: random(0.4, 0.75) * width, y: random(height) },
      p4: { x: width, y: random(0.7, 1) * height },
      velocidad: {
        p1: random(0.005, 0.02),
        p2: random(0.005, 0.02),
        p3: random(0.005, 0.02),
        p4: random(0.005, 0.02),
      },
      offset: {
        p1: random(TWO_PI),
        p2: random(TWO_PI),
        p3: random(TWO_PI),
        p4: random(TWO_PI),
      },
    };
    beziers.push(bez);
  }
}

function draw() {
  background("rgba(0, 0, 12, 0.06)");
  for (let bez of beziers) {
    updatePoints(bez);
    drawTangents(bez);
  }
}

function updatePoints(bez) {
  // Actualizar puntos de control con velocidades y offsets únicos
 	bez.p1.x = 0;
	bez.p1.y = map(sin(frameCount * bez.velocidad.p1 + bez.offset.p1),
    -1, 1, 0, height * 0.3);
  bez.p2.x = map(sin(frameCount * bez.velocidad.p2 + bez.offset.p2),
    -1, 1, width * 0.25, width * 0.6);
  bez.p2.y = map(cos(frameCount * bez.velocidad.p2 + bez.offset.p2),
    -1, 1, 0, height);
  bez.p3.x = map(cos(frameCount * bez.velocidad.p3 + bez.offset.p3),
    -1, 1, width * 0.4, width * 0.75);
  bez.p3.y = map(sin(frameCount * bez.velocidad.p3 + bez.offset.p3),
    -1, 1, 0, height);
	bez.p4.x = width-1;
  bez.p4.y = map(cos(frameCount * bez.velocidad.p4 + bez.offset.p4),
    -1, 1, height * 0.7, height);
}

function drawTangents(bez) {
  strokeWeight(1);
  stroke(255, 96);
  for (let f = 0; f <= 1; f += 0.004) {
    const x = bezierPoint(bez.p1.x, bez.p2.x, bez.p3.x, bez.p4.x, f);
    const y = bezierPoint(bez.p1.y, bez.p2.y, bez.p3.y, bez.p4.y, f);
    const tx = 2 * bezierTangent(bez.p1.x, bez.p2.x, bez.p3.x, bez.p4.x, f);
    const ty = 2 * bezierTangent(bez.p1.y, bez.p2.y, bez.p3.y, bez.p4.y, f);
    const vec = createVector(tx, ty).normalize().mult(100); // speed issue: (2 * max(width, height));
    const ang = vec.heading();
		const clrNoise = (noise((x+tx)/1234, (y+ty)/4321, frameCount/22)-0.5)*60;
    const clrHue = (ang / TWO_PI * 360 + clrNoise + 360) % 360;
		stroke(clrHue, 75, 75, 0.2);
    line(x + vec.x, y + vec.y, x - vec.x, y - vec.y);
  }
}

function mousePressed() {
  if (mouseButton === LEFT) setup(); // reset beziers
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
	background("rgb(0, 0, 12)");
}
